/**
 * Men's Health Compass: Prostatic Artery Embolization (PAE) Candidacy Assessment
 * Based on SIR guidelines and peer-reviewed literature
 */

export interface PatientData {
  age: string;
  sex: string;
  bmi: string;
  prostateVolume: string;
  psa: string;
  symptomDuration: string;
}

export interface AssessmentData {
  // Symptom scores
  ipssScore: number;
  ipssQol: number;
  peakFlowRate: string; // Qmax ml/s
  postVoidResidual: string; // PVR ml

  // Clinical criteria
  prostateVolumeOver40: boolean;
  failedMedicalTherapy: boolean;
  symptomDurationOver6Months: boolean;
  urinaryRetentionHistory: boolean;
  recurrentUTI: boolean;
  recurrentHematuria: boolean;

  // Prior treatments
  priorInterventions: string[];

  // Imaging
  mriPerformed: boolean;
  ctaPerformed: boolean;
  middleLobeEnlargement: boolean;
  bilateralDisease: boolean;

  // Exclusion criteria
  noProstateCancer: boolean;
  noBladderCancer: boolean;
  noNeurogenicBladder: boolean;
  noUrethralStricture: boolean;
  noActiveUTI: boolean;
  noCoagulopathy: boolean;
  noSevereAtherosclerosis: boolean;
  noRenalInsufficiency: boolean;
}

export interface ScoringResult {
  score: number;
  label: "Strong Candidate" | "Moderate Candidate" | "Weak Candidate" | "Not Indicated";
  color: "primary" | "warning" | "destructive";
  summary: string;
  criteriaMetCount: number;
  criteriaTotalCount: number;
}

export function computePAEScore(assessment: AssessmentData): ScoringResult {
  let score = 0;
  const criteriaMet: boolean[] = [];

  // IPSS scoring (max 20)
  if (assessment.ipssScore >= 20) {
    score += 20;
    criteriaMet.push(true);
  } else if (assessment.ipssScore >= 13) {
    score += 15;
    criteriaMet.push(true);
  } else if (assessment.ipssScore >= 8) {
    score += 8;
    criteriaMet.push(true);
  } else {
    score += 3;
    criteriaMet.push(false);
  }

  // IPSS QoL (max 10)
  if (assessment.ipssQol >= 4) {
    score += 10;
    criteriaMet.push(true);
  } else if (assessment.ipssQol >= 3) {
    score += 6;
    criteriaMet.push(true);
  } else {
    score += 2;
    criteriaMet.push(false);
  }

  // Prostate volume (max 15)
  if (assessment.prostateVolumeOver40) {
    score += 15;
    criteriaMet.push(true);
  } else {
    criteriaMet.push(false);
  }

  // Mandatory criteria (10 pts each = 30 total)
  const mandatoryCriteria = [
    assessment.failedMedicalTherapy,
    assessment.symptomDurationOver6Months,
    assessment.noProstateCancer,
  ];
  mandatoryCriteria.forEach((met) => {
    if (met) score += 10;
    criteriaMet.push(met);
  });

  // Bonus criteria (5 pts each, max 15)
  if (assessment.urinaryRetentionHistory) {
    score += 5;
  }
  if (assessment.mriPerformed || assessment.ctaPerformed) {
    score += 5;
  }
  if (assessment.noActiveUTI && assessment.noCoagulopathy) {
    score += 5;
  }

  const criteriaMetCount = criteriaMet.filter(Boolean).length;
  const criteriaTotalCount = criteriaMet.length;

  // Hard disqualifiers
  if (!assessment.noProstateCancer) {
    return {
      score: Math.min(score, 20),
      label: "Not Indicated",
      color: "destructive",
      summary:
        "Active prostate malignancy is an absolute contraindication. PAE is not indicated until malignancy is ruled out or treated.",
      criteriaMetCount,
      criteriaTotalCount,
    };
  }

  if (!assessment.noActiveUTI) {
    return {
      score: Math.min(score, 25),
      label: "Not Indicated",
      color: "destructive",
      summary:
        "Active urinary tract infection must be treated before PAE can be considered.",
      criteriaMetCount,
      criteriaTotalCount,
    };
  }

  if (score >= 75) {
    return {
      score: Math.min(score, 100),
      label: "Strong Candidate",
      color: "primary",
      summary:
        "Patient demonstrates significant LUTS with adequate prostate volume and failed medical therapy. Optimal profile for prostatic artery embolization.",
      criteriaMetCount,
      criteriaTotalCount,
    };
  }

  if (score >= 50) {
    return {
      score,
      label: "Moderate Candidate",
      color: "warning",
      summary:
        "Patient may benefit from PAE but incomplete criteria met. Consider multidisciplinary review with urology before proceeding.",
      criteriaMetCount,
      criteriaTotalCount,
    };
  }

  return {
    score,
    label: "Weak Candidate",
    color: "destructive",
    summary:
      "Insufficient evidence to support PAE candidacy. Consider further medical optimization or alternative interventions.",
    criteriaMetCount,
    criteriaTotalCount,
  };
}
